<div><h1 class="h4 mb-3">My performance reviews</h1>@error('performance')<div class="alert alert-danger">{{$message}}</div>@enderror @forelse($reviews as $r)<div class="card mb-3"><div class="card-body"><div class="d-flex justify-content-between"><strong>{{$r->cycle->name}}</strong><span class="badge text-bg-light">{{$r->status}}</span></div><div class="row mt-3"><div class="col-md-4">Overall: {{$r->overall_rating}}</div><div class="col-md-4">Goals: {{$r->goals_rating}}</div><div class="col-md-4">Competency: {{$r->competency_rating}}</div></div><hr><p><strong>Strengths:</strong> {{$r->strengths ?: '—'}}</p><p><strong>Improvements:</strong> {{$r->improvements ?: '—'}}</p><p><strong>Goals:</strong> {{$r->goals ?: '—'}}</p>@if($r->status==='submitted')<textarea class="form-control mb-2" wire:model="comments.{{$r->id}}" placeholder="Optional employee comment"></textarea><button class="btn btn-primary" wire:click="acknowledge({{$r->id}})">Acknowledge review</button>@else<p class="text-muted mb-0">Acknowledged {{$r->acknowledged_at?->toDateTimeString()}}</p>@endif</div></div>@empty<div class="alert alert-light">No submitted performance reviews.</div>@endforelse</div>
